    return api.orders.handle_create({"customer_id": customer_id, "items": [{"sku": sku, "quantity": quantity}]})


def test_order_history_for_unknown_customer_is_not_found(shop):
    response = shop.insights.handle_order_history("nobody")

    assert response.status == 404
    assert response.body == {"error": "customer not found"}


def test_order_history_for_customer_without_orders_is_empty(shop):
    response = shop.insights.handle_order_history("c1")

    assert response.status == 200
    assert response.body == {"customer_id": "c1", "orders": []}


def test_order_history_lists_newest_order_first(shop):
    first = place(shop, "c1", "PEN", 1).body["order_id"]
    second = place(shop, "c1", "BOOK", 1).body["order_id"]

    response = shop.insights.handle_order_history("c1")

    assert [o["order_id"] for o in response.body["orders"]] == [second, first]


def test_order_history_total_matches_discounted_order_summary(shop):
    order_id = place(shop, "c1", "LAMP", 2).body["order_id"]

    entry = shop.insights.handle_order_history("c1").body["orders"][0]

    assert entry == {"order_id": order_id, "status": "placed", "total_cents": 10_800}
    assert shop.orders.handle_get(order_id).body["total_cents"] == 10_800


def test_order_history_includes_cancelled_orders_with_status(shop):
    order_id = place(shop, "c1", "PEN", 1).body["order_id"]
    shop.orders.handle_cancel(order_id)

    entry = shop.insights.handle_order_history("c1").body["orders"][0]

    assert entry["status"] == "cancelled"


def test_order_history_excludes_other_customers_orders(shop):
    place(shop, "c2", "PEN", 1)

    assert shop.insights.handle_order_history("c1").body["orders"] == []

